head.script:
scwin.checkVal = function() {
	return !(document.getElementById("popup_window_wframe_drag") || document.getElementById("mf_popup_window_wframe_drag"));
};
scwin.trigger4_onclick = function(e) {
	var opts = {
		"id": "popup_window_wframe",
		"type": "window",
		"width": "300px",
		"height": "300px",
		"top": 250,
		"left": 250,
		"popupName": "focusTest",
		"modal": false,
		"useIFrame": true,
		"title": "focusTest",
		"frameMode": "wframe"
	};
	WebSquare.util.openPopup("/sample/common_link/p_popup_gostLayer_SKT-715_(WSQ-2362)_popup.xml", opts);
};
